create table if not exists public.customers (id uuid primary key default gen_random_uuid(), name text not null, phone text, email text, address text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.projects (id uuid primary key default gen_random_uuid(), customer_id uuid references public.customers(id), name text not null, code text not null unique, status text not null default 'draft' check (status in ('draft','measurement','design','calculated','quoted','approved','production','delivered','closed')), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.materials (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, category text not null, thickness_mm numeric not null default 0, sheet_length_mm numeric, sheet_width_mm numeric, unit_cost numeric not null default 0, edge_cost_per_m numeric not null default 0, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.project_measurements (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, name text not null, room text, width_mm numeric not null default 0, depth_mm numeric, height_mm numeric not null default 0, wall_width_mm numeric, wall_height_mm numeric, notes text, measured_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.furniture_items (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, measurement_id uuid references public.project_measurements(id), name text not null, type text not null, quantity integer not null default 1 check (quantity > 0), width_mm numeric not null default 0, depth_mm numeric not null default 0, height_mm numeric not null default 0, configuration jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.furniture_components (id uuid primary key default gen_random_uuid(), furniture_item_id uuid not null references public.furniture_items(id) on delete cascade, component_type text not null, name text not null, quantity integer not null default 1, length_mm numeric not null default 0, width_mm numeric not null default 0, thickness_mm numeric not null default 0, material_id uuid references public.materials(id), edge_banding jsonb not null default '{}'::jsonb, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.calculation_runs (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, furniture_item_id uuid references public.furniture_items(id) on delete set null, engine_version text not null, input_snapshot jsonb not null, result jsonb not null, status text not null default 'valid' check (status in ('valid','invalid','superseded')), created_at timestamptz not null default now());
create table if not exists public.cutting_list_items (id uuid primary key default gen_random_uuid(), calculation_run_id uuid not null references public.calculation_runs(id) on delete cascade, project_id uuid not null references public.projects(id) on delete cascade, furniture_item_id uuid references public.furniture_items(id) on delete set null, component_id uuid references public.furniture_components(id) on delete set null, sequence_no integer not null, part_name text not null, material_id uuid references public.materials(id), length_mm numeric not null default 0, width_mm numeric not null default 0, thickness_mm numeric not null default 0, quantity integer not null default 1, edge_banding jsonb not null default '{}'::jsonb, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(calculation_run_id, sequence_no));
create index if not exists idx_projects_customer on public.projects(customer_id); create index if not exists idx_measurements_project on public.project_measurements(project_id); create index if not exists idx_furniture_project on public.furniture_items(project_id); create index if not exists idx_components_furniture on public.furniture_components(furniture_item_id); create index if not exists idx_calculations_project on public.calculation_runs(project_id); create index if not exists idx_cutting_project on public.cutting_list_items(project_id);
alter table public.customers enable row level security; alter table public.projects enable row level security; alter table public.materials enable row level security; alter table public.project_measurements enable row level security; alter table public.furniture_items enable row level security; alter table public.furniture_components enable row level security; alter table public.calculation_runs enable row level security; alter table public.cutting_list_items enable row level security;
do $$ declare t text; begin foreach t in array array['customers','projects','materials','project_measurements','furniture_items','furniture_components','calculation_runs','cutting_list_items'] loop execute format('drop policy if exists %I on public.%I', 'millimetre_authenticated_all_'||t, t); execute format('create policy %I on public.%I for all to authenticated using (true) with check (true)', 'millimetre_authenticated_all_'||t, t); end loop; end $$;